    19	
    20	/** Props for StaticProductHeader — the base `ProductViewHeaderProps` surface plus the
    21	 * page-only `isPriceLoading` flag that suppresses Was/Now during a variant re-fetch. */
    22	type StaticProductHeaderProps = ProductViewHeaderProps & {
    23	  isPriceLoading?: boolean;
    24	};
    25	
    26	/**
    27	 * Replaces the title/price block of ProductView's header with the Zimmermann content group.
    28	 *
    29	 * The breadcrumb and promo callout are reproduced from the base header rather than dropped:
    30	 * `renderHeader` replaces the whole header block, and neither of those belongs to SFCC-89
    31	 * (breadcrumb is SFCC-578, badges are SFCC-132/225), so losing them here would be a
    32	 * regression rather than a scope decision.
    33	 *
    34	 * ProductView renders this once per breakpoint, so it stays free of side effects.
    35	 *
    36	 * A component rather than the bare render function it was on the page, so that it can hold
    37	 * `useIntl()` itself — `formatPrice` needs `formatNumber`. components.md exempts `useIntl` from
    38	 * the container/presentational rule because it reads a Provider mounted above the route tree.
    39	 * `isPriceLoading` is the one addition beyond `ProductViewHeaderProps`: it is a page-level
    40	 * concern (keepPreviousData stale-price suppression) that cannot live on the base prop surface.
    41	 * `useIntl()` throws without an `IntlProvider`, so anything rendering this must supply one:
    42	 * the app does in the base `_app`, `.storybook/preview.tsx` does for the stories.
    43	 */
    44	export const StaticProductHeader = ({
    45	  name,
    46	  product: headerProduct,
    47	  priceData,
    48	  currency,
    49	  category: headerCategory,
    50	  isProductPartOfBundle,
    51	  isPriceLoading,
    52	  wishlistButton,
    53	}: StaticProductHeaderProps) => {
    54	  // react-intl returns already-bound methods, so destructuring them cannot unbind anything —
    55	  // the rule cannot see that. Same suppression, and same reason, as the page's own `useIntl`.
    56	  // eslint-disable-next-line @typescript-eslint/unbound-method
    57	  const { formatNumber } = useIntl();
    58	
    59	  // This is the live formatter — the header is the only place a price is rendered. The page
    60	  // declares an identical one, but only to satisfy `selectPdpProductInfo`'s required parameter:
    61	  // it passes `null` for `priceData`, so its copy never executes. Not a leftover of this
    62	  // extraction, and not a value that can drift out of step with this one.
    63	  const formatPrice = (amount: number, priceCurrency: string) =>
    64	    formatNumber(amount, { style: 'currency', currency: priceCurrency });
    65	
    66	  const info = selectPdpProductInfo(headerProduct ?? { name }, priceData, currency ?? '', formatPrice);
    67	  const hasBadges = Boolean(info?.badges && info.badges.length > 0);
    68	
    69	  return (
    70	    // spacing={0}: every gap below is now an explicit marginTop on the element that needs it,
    71	    // not the Stack's shared `gap` — so each one is a single value visible in devtools at the
    72	    // point it applies, rather than a value that only makes sense added to a sibling gap.
    73	    <VStack spacing={0} align="flex-start" marginBottom={[4, 4, 4, 0, 0]}>
    74	      <VStack spacing="var(--zimm-scale-xs)" align="flex-start">
    75	        {/* Breadcrumb — SFCC-578, not yet implemented. Uncomment when ready. */}
    76	        {/* {headerCategory && (
    77	          <Skeleton isLoaded={headerCategory} minWidth={64}>
    78	            <Breadcrumb categories={headerCategory} />
    79	          </Skeleton>
    80	        )} */}
    81	
    82	        {/* ZimmProductBadges renders nothing when there are no badges — no extra guard needed
    83	            beyond info itself being resolved. */}
    84	        {info && <ZimmProductBadges badges={info.badges} />}
    85	      </VStack>
    86	
    87	      {/*
    88	       * Layout per Figma node 40003021:101731 ("Product name and Wishlist") — name (left) +
    89	       * wishlist badge (right) in one row, then price, then description below. ZimmProductContent
    90	       * owns the row/gap layout internally (its own nameRow/nameWrapper recipe parts); this file
    91	       * only supplies the wishlist badge via the wishlistButton prop.
    92	       *
    93	       * (SFCC-737 cited a different node, 40000307:13968, for what it called the same "Product
    94	       * name and Wishlist" element while this branch was in flight — not reconciled here; flagged
    95	       * for whoever owns the Figma file to confirm which one is current.)
    96	       *
    97	       * `data-testid="product-content"` comes from ZimmProductContent itself, so stories can
    98	       * assert its presence/absence without coupling to individual child testids.
    99	       */}
   100	      <Box
   101	        data-testid="name-block-wrapper"
   102	        marginTop={hasBadges ? 'var(--zimm-scale-l)' : 'var(--zimm-scale-xs)'}
   103	      >
   104	      <Skeleton isLoaded={Boolean(info)} minHeight="var(--zimm-font-lineheight-2xs)">
   105	        {info && (
   106	          // h2, not h1: the page already emits a screen-reader-only
   107	          // <h1>Product Details</h1>, and the base header this replaces rendered the name
   108	          // as an h2. Changing the outline is SEO's call, not a side-effect of this ticket.
   109	          <ZimmProductContent
   110	            name={info.name}
   111	            headingLevel="h2"
   112	            // The base header gates its price and its promo together behind the same
   113	            // `!isProductPartOfBundle` check. The promo is gated below; without this the
   114	            // price would be the one part of that header which stopped being gated.
   115	            currentPrice={isProductPartOfBundle ? undefined : info.price}
   116	            originalPrice={isProductPartOfBundle ? undefined : info.wasPrice}
   117	            isPriceLoading={!isProductPartOfBundle && isPriceLoading}
   118	            description={info.description}
   119	            // Already resolves to undefined for bundle children — ProductView's own
   120	            // renderWishlistToggle() omits it whenever isProductPartOfBundle, so no
   121	            // second gate is needed here (SFCC-434).
   122	            wishlistButton={wishlistButton}
   123	          />
   124	        )}
   125	      </Skeleton>
   126	      </Box>
   127	
   128	      {!isProductPartOfBundle && (
   129	        // marginTop replaces what the outer VStack's spacing used to contribute here — same
   130	        // 8px as before, just explicit now that spacing={0} above stops supplying it.
   131	        <Skeleton isLoaded={Boolean(headerProduct)} marginTop="var(--zimm-scale-xs)">
   132	          {headerProduct?.productPromotions && <PromoCallout product={headerProduct} />}
   133	        </Skeleton>
   134	      )}
   135	    </VStack>
   136	  );
   137	};

